type Request=(path:string,init?:RequestInit)=>Promise<Response>;
type FieldType="TEXT"|"TEXTAREA"|"NUMBER"|"DROPDOWN"|"MULTI_SELECT"|"DATE"|"CHECKBOX"|"FILE_UPLOAD"|"IMAGE_UPLOAD"|"AIRCRAFT_SELECT"|"SECTION";
type Field={key:string;label:string;type:FieldType;helpText?:string|null;required:boolean;order:number;binding?:DefectBinding|null;visible?:boolean|null;readOnly?:boolean|null;visibleWhen?:{fieldKey:string;equals:string}|null;requiredWhen?:{fieldKey:string;equals:string}|null;textRules?:{minLength?:number|null;maxLength?:number|null;alphaOnly?:boolean;alphanumeric?:boolean;pattern?:string|null}|null;numericRules?:{min?:number|null;max?:number|null;precision?:number|null}|null;dateRules?:{minDate?:string|null;maxDate?:string|null}|null;optionSource?:string|null;optionFilter?:{areaFieldKey?:string|null;componentFieldKey?:string|null}|null;fileRules?:{extensions:string[];mimeTypes:string[];maxFileSizeBytes:number;minCount:number;maxCount:number;maxTotalSizeBytes?:number|null}|null};
type FormConfig={fields:Field[]};
