type Version={id:string;formId:string;versionNumber:number;status:string;configuration:FormConfig;formName?:string;areaId?:string;areaIds?:string[];purpose?:Purpose;workflowStage?:Stage;createdBy?:string;createdAt?:string;publishedBy?:string|null;publishedAt?:string|null};
