type BindingInfo={binding:DefectBinding;stableKey:string;name:string;domainProperty:string;destinationTable:string;destinationColumn:string;dataType:string;supportedFieldTypes:FieldType[];cabinAreaCodes:string[];formPurposes:Purpose[];requiredPolicy:string;referenceDataSource:string|null;validation:string;classification:string;multipleAllowed:boolean;dependsOnBinding:string|null};
