const stagesByPurpose:Record<Purpose,Stage[]>={DEFECT_REPORT:["INITIAL_REPORT"],REVIEW_DECISION:["REPORTED","UNDER_REVIEW"],INSPECTION:["INSPECTION_REQUIRED","INSPECTION_IN_PROGRESS"],CORRECTIVE_ACTION:["ACTION_ASSIGNED","IN_PROGRESS"],VERIFICATION:["AWAITING_VERIFICATION"],CLOSURE_APPROVAL:["APPROVAL_REQUIRED"],REOPEN:["CLOSED"]};
